/**
 * Mendapatkan asset URI (rbxassetid://<id>) dari nama icon Lucide (kebab-case).
 * Contoh: GetIconUri("message-square"), GetIconUri("music"), GetIconUri("settings")
 */
export function GetIconUri(name: string): string {
	const assetId = LUCIDE_REGISTRY[name];
	if (assetId !== undefined) {
		return `rbxassetid://${assetId}`;
	}
	warn(`[LucideIcons] Icon "${name}" tidak ditemukan di registri.`);
	return "";
}

/**
 * Mengecek apakah icon Lucide dengan nama tertentu tersedia.
 */
export function HasLucideIcon(name: string): boolean {
	return LUCIDE_REGISTRY[name] !== undefined;
}
